#include "textutil.h"

//==========================================
// DYNAMIC PROGRAMMING MODULE (HOA 12)
// A problem is solved once for its small parts, and the answers are remembered
// (memoization = top down, tabulation = bottom up), instead of being computed again and again.
//
// fibonacciMemo / fibonacciNaive : the classic example, used in the Algorithm lab to show the speed difference
// bestBundle                     : 0/1 knapsack, which wishlist games give the most value for a budget
// editDistance                   : fewest edits between two texts, used for "Did you mean ...?" in the search
//==========================================

// slow version, T(n) = T(n-1) + T(n-2), about 1.6^n calls. Only for demonstration with small n.
//--- fibonacciNaive -------------------------------------------------------------------------------
// What    : Plain recursive Fibonacci, about 1.6^n calls. Only for the demonstration in the
//           Algorithm lab.
// Returns : the Fibonacci number
// Used by : doLab (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline long long fibonacciNaive(int n, long long* calls = nullptr) {
    if (calls != nullptr) (*calls)++;
    if (n < 2) return n;
    return fibonacciNaive(n - 1, calls) + fibonacciNaive(n - 2, calls);
}

// memoized version: every value is computed one time, O(n) calls.
//--- fibonacciMemoStep ----------------------------------------------------------------------------
// What    : The recursive part of the memoized Fibonacci: a value already in the memo table is not
//           computed again.
// Returns : the Fibonacci number
// Used by : fibonacciMemo
//--------------------------------------------------------------------------------------------------
inline long long fibonacciMemoStep(int n, std::vector<long long>& memo, long long* calls) {
    if (calls != nullptr) (*calls)++;
    if (n < 2) return n;
    if (memo[(size_t)n] != -1) return memo[(size_t)n];
    memo[(size_t)n] = fibonacciMemoStep(n - 1, memo, calls) + fibonacciMemoStep(n - 2, memo, calls);
    return memo[(size_t)n];
}

//--- fibonacciMemo --------------------------------------------------------------------------------
// What    : Memoized Fibonacci (top down dynamic programming), O(n) calls.
// Returns : the Fibonacci number
// Used by : doLab (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline long long fibonacciMemo(int n, long long* calls = nullptr) {
    if (n < 0) return 0;
    std::vector<long long> memo((size_t)n + 1, -1);
    return fibonacciMemoStep(n, memo, calls);
}

// one wishlist game that may go in the bundle
struct BundleItem {
    int gameId = 0;
    int costCents = 0;
    int value = 0;              // how much the player wants it (for example the recommend percent)
};

// the answer of the knapsack
struct BundleResult {
    int totalCostCents = 0;
    int totalValue = 0;
    std::vector<int> gameIds;   // the chosen games, in the order of the input
};

// 0/1 knapsack, bottom up table. table[i][w] = best value using the first i items with w cents.
// Costs are divided by "step" cents (default 100 = whole dollars) to keep the table small.
// Items with cost 0 are always taken. O(items * budget / step).
//--- bestBundle -----------------------------------------------------------------------------------
// What    : 0/1 knapsack with a bottom up table: picks the wishlist games with the highest total
//           value that fit the budget. Costs are counted in whole dollars to keep the table small,
//           rounded up so the budget is never exceeded.
// Returns : the chosen game ids with total cost and value
// Used by : doBundle (screens.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline BundleResult bestBundle(const std::vector<BundleItem>& items, int budgetCents, int step = 100) {
    BundleResult result;
    if (budgetCents <= 0 || step <= 0) return result;
    int n = (int)items.size();
    int capacity = budgetCents / step;
    std::vector<std::vector<int>> table((size_t)n + 1, std::vector<int>((size_t)capacity + 1, 0));
    std::vector<int> weight((size_t)n);
    for (int i = 0; i < n; i++) weight[(size_t)i] = (items[(size_t)i].costCents + step - 1) / step;   // round up, never over budget

    for (int i = 1; i <= n; i++) {
        for (int w = 0; w <= capacity; w++) {
            table[(size_t)i][(size_t)w] = table[(size_t)i - 1][(size_t)w];                      // skip item i
            if (weight[(size_t)i - 1] <= w) {                                                   // or take it
                int taken = table[(size_t)i - 1][(size_t)(w - weight[(size_t)i - 1])] + items[(size_t)i - 1].value;
                if (taken > table[(size_t)i][(size_t)w]) table[(size_t)i][(size_t)w] = taken;
            }
        }
    }

    // walk the table backwards to find which items were taken
    int w = capacity;
    for (int i = n; i >= 1; i--) {
        if (table[(size_t)i][(size_t)w] != table[(size_t)i - 1][(size_t)w]) {
            result.gameIds.push_back(items[(size_t)i - 1].gameId);
            result.totalCostCents += items[(size_t)i - 1].costCents;
            result.totalValue += items[(size_t)i - 1].value;
            w -= weight[(size_t)i - 1];
        }
    }
    std::reverse(result.gameIds.begin(), result.gameIds.end());
    return result;
}

// Levenshtein distance: the fewest insertions, deletions and replacements that turn a into b.
// table[i][j] = distance between the first i characters of a and the first j of b. Counts characters, not bytes.
//--- editDistance ---------------------------------------------------------------------------------
// What    : Levenshtein distance by dynamic programming: the fewest insertions, deletions and
//           replacements that turn one text into the other. Counts UTF-8 characters.
// Returns : the number of edits
// Used by : closestTitle (store.h), doShowcase (screens.h)
//--------------------------------------------------------------------------------------------------
inline int editDistance(const std::string& a, const std::string& b) {
    // split both texts in UTF-8 characters
    std::vector<std::string> x, y;
    for (size_t i = 0; i < a.size();) {
        size_t len = 1;
        while (i + len < a.size() && utf8IsContinuation((unsigned char)a[i + len])) len++;
        x.push_back(a.substr(i, len));
        i += len;
    }
    for (size_t i = 0; i < b.size();) {
        size_t len = 1;
        while (i + len < b.size() && utf8IsContinuation((unsigned char)b[i + len])) len++;
        y.push_back(b.substr(i, len));
        i += len;
    }
    size_t n = x.size(), m = y.size();
    std::vector<std::vector<int>> table(n + 1, std::vector<int>(m + 1, 0));
    for (size_t i = 0; i <= n; i++) table[i][0] = (int)i;
    for (size_t j = 0; j <= m; j++) table[0][j] = (int)j;
    for (size_t i = 1; i <= n; i++) {
        for (size_t j = 1; j <= m; j++) {
            int same = (x[i - 1] == y[j - 1]) ? 0 : 1;
            int best = table[i - 1][j - 1] + same;                          // replace (or keep)
            if (table[i - 1][j] + 1 < best) best = table[i - 1][j] + 1;     // delete
            if (table[i][j - 1] + 1 < best) best = table[i][j - 1] + 1;     // insert
            table[i][j] = best;
        }
    }
    return table[n][m];
}

#endif //STEAM_DP_H
